for (const [panel, rows] of terminalByPanel.entries()) {
  // Keep the archive's row order. The terminal record explicitly says wall
  // clocks do not order the event stream; sequence is monotonic within a live
  // feed/board, so re-sorting by timestamp would invent an ordering source.
  const paints = rows.filter((row) => row.event === "P");

